def count_neighbors(grid, r, c):
    """Count 4-connected neighbors of same value"""
    count = 0
    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
            if grid[nr][nc] == grid[r][c]:
                count += 1
    return count

