# Also try: keep only pixels that are part of connected components with size >= 2
def keep_larger_components(grid, min_size=2):
    visited = set()
    components = []

    for start_r in range(len(grid)):
        for start_c in range(len(grid[0])):
            if (start_r, start_c) in visited:
                continue
            if grid[start_r][start_c] == 0:
                continue

            component = []
            queue = [(start_r, start_c)]
            while queue:
                r, c = queue.pop(0)
                if (r, c) in visited:
                    continue
                visited.add((r, c))
                component.append((r, c))
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                        if (nr, nc) not in visited and grid[nr][nc] == grid[r][c]:
                            queue.append((nr, nc))

            if len(component) >= min_size:
                components.append(set(component))

    result = [[0]*len(grid[0]) for _ in range(len(grid))]
    for comp in components:
        for r, c in comp:
            result[r][c] = grid[r][c]
    return result

