# Let me try yet another hypothesis: remove ALL isolated pixels regardless of direction
def get_components(grid, val):
    """Get all 4-connected components of value val"""
    visited = set()
    components = []
    H, W = len(grid), len(grid[0])

    for r in range(H):
        for c in range(W):
            if grid[r][c] == val and (r,c) not in visited:
                comp = []
                stack = [(r,c)]
                while stack:
                    cr, cc = stack.pop()
                    if (cr, cc) in visited:
                        continue
                    visited.add((cr, cc))
                    comp.append((cr, cc))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < H and 0 <= nc < W:
                            if grid[nr][nc] == val and (nr, nc) not in visited:
                                stack.append((nr, nc))
                components.append(comp)
    return components

def remove_small_components(grid, min_size, val=4):
    """Remove components smaller than min_size"""
    components = get_components(grid, val)

    # Mark all pixels in small components
    to_remove = set()
    for comp in components:
        if len(comp) < min_size:
            to_remove.update(comp)

    result = [[grid[r][c] if (r,c) not in to_remove else 0 
               for c in range(len(grid[0]))] for r in range(len(grid))]
    return result

