def get_components_connected_to_top(grid, val=4):
    """Get connected components and mark which ones connect to top rows (0-8)"""
    H, W = len(grid), len(grid[0])

    # BFS/DFS to find component membership and connection to top
    visited = [[False]*W for _ in range(H)]
    component_id = [[-1]*W for _ in range(H)]
    comp_to_top = {}  # component_id -> True if connects to rows 0-8

    comp_counter = 0

    for r in range(H):
        for c in range(W):
            if grid[r][c] == val and not visited[r][c]:
                # New component
                q = [(r,c)]
                visited[r][c] = True
                component_cells = []
                reaches_top = False

                idx = 0
                while idx < len(q):
                    cr, cc = q[idx]
                    idx += 1

                    component_cells.append((cr, cc))

                    if cr <= 8:  # Touches top rows
                        reaches_top = True

                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < H and 0 <= nc < W:
                            if grid[nr][nc] == val and not visited[nr][nc]:
                                visited[nr][nc] = True
                                q.append((nr, nc))

                comp_id = comp_counter
                comp_counter += 1
                for cr, cc in component_cells:
                    component_id[cr][cc] = comp_id

                if reaches_top:
                    comp_to_top[comp_id] = True

    return component_id, comp_to_top

